import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input_str = scanner.next();
        int length = input_str.length();
        int at_flag = 0;
        StringBuilder output_str = new StringBuilder();
        output_str.append(input_str.charAt(0));
        int index = 1;
        while (index < length) {
            if (index + 2 < length && input_str.substring(index, index + 3).equals("dot") && index + 3 != length) {
                output_str.append('.');
                index += 3;
            } else if (input_str.charAt(index) == 'a') {
                if (index + 1 < length && input_str.charAt(index + 1) == 't' && at_flag == 0) {
                    output_str.append('@');
                    at_flag = 1;
                    index++;
                } else {
                    output_str.append(input_str.charAt(index));
                }
            } else {
                output_str.append(input_str.charAt(index));
            }
            index++;
        }
        System.out.print(output_str.toString());
        scanner.close();
    }
}
